package Jagged_array;

public class Three_rows {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[][] arr=new int[3][];
		arr[0]=new int[2];
		arr[1]=new int[4];
		arr[2]=new int[3];
		
		System.out.println("First row elements: "+arr[0].length);
		System.out.println("First row elements: "+arr[1].length);
		System.out.println("First row elements: "+arr[2].length);
		
	}

}
